*/
scwin.dataValidation = async function () {
    /* sdd-asis-lifecycle:begin dataValidation — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const nullInput = $("table[name=conTable] input:visible[name!=''][type='text'][value='']");
    for (let i = 0; i < nullInput.length; i++) {
        if ($c.str.getByteLength($($(nullInput)[i]).val()) == 0) {
            const ipNm = $($(nullInput)[i]).attr("name");
            if ($($(nullInput)[i]).attr("id") === "nusual_isu_cond_contn") {
                continue;
            }
            const labelNm = $('[for="' + ipNm + '"]').text();
            await $c.win.alert(labelNm + "의 값이 입력되지 않았습니다.");
            console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return true;
        }
    }
    if (($c.util.getComponent('ipt_cfiCd').getValue() == null ? '' : String($c.util.getComponent('ipt_cfiCd').getValue())) === '') {
        await $c.win.alert("CFI_CD를 입력하세요");
        $c.util.getComponent("ipt_cfiCd").focus();
        return true;
    }
    if (($c.util.getComponent('ipt_applComNm').getValue() == null ? '' : String($c.util.getComponent('ipt_applComNm').getValue())) === '') {
        await $c.win.alert("소속기관을 입력하세요");
        $c.util.getComponent("ipt_applComNm").focus();
        return true;
    }
    if (($c.util.getComponent('ipt_apctNm').getValue() == null ? '' : String($c.util.getComponent('ipt_apctNm').getValue())) === '') {
        await $c.win.alert("이름을 입력하세요");
        $c.util.getComponent("ipt_apctNm").focus();
        return true;
    }
    if (($c.util.getComponent('ipt_ph02').getValue() == null ? '' : String($c.util.getComponent('ipt_ph02').getValue())) === '' || ($c.util.getComponent('ipt_ph03').getValue() == null ? '' : String($c.util.getComponent('ipt_ph03').getValue())) === '') {
        await $c.win.alert("전화번호를 입력하세요");
        $c.util.getComponent("ipt_ph02").focus();
        return true;
    }
    if (($c.util.getComponent('ipt_ph02').getValue() == null ? '' : String($c.util.getComponent('ipt_ph02').getValue())) === '' || ($c.util.getComponent('ipt_ph03').getValue() == null ? '' : String($c.util.getComponent('ipt_ph03').getValue())) === '') {
        await $c.win.alert("전화번호를 입력하세요");
        $c.util.getComponent("ipt_ph02").focus();
        return true;
    }
    if (($c.util.getComponent('ipt_fax02').getValue() == null ? '' : String($c.util.getComponent('ipt_fax02').getValue())) === '' || ($c.util.getComponent('ipt_fax03').getValue() == null ? '' : String($c.util.getComponent('ipt_fax03').getValue())) === '') {
        await $c.win.alert("팩스번호를 입력하세요");
        $c.util.getComponent("ipt_fax02").focus();
        return true;
    }
    if (($c.util.getComponent('ipt_email01').getValue() == null ? '' : String($c.util.getComponent('ipt_email01').getValue())) === '' || ($c.util.getComponent('ipt_email02').getValue() == null ? '' : String($c.util.getComponent('ipt_email02').getValue())) === '') {
        await $c.win.alert("이메일을 입력하세요");
        $c.util.getComponent("ipt_email01").focus();
        return true;
    }
    if ($("input[key=ef_cp_isu_nm][value='']").length > 0) {
        await $c.win.alert("이자분리채권 을 입력해야 합니다.");
        return true;
    }
    return false;
    /* sdd-asis-lifecycle:end */
};


